WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_analysis_option'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '选项判定', 'kp-xingce-data-analysis-option', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "选项判定（综合分析篇）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "每篇资料的压轴大题“能够推出/不能推出的是？”。通过调整验证优先级，大幅压缩时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "资料分析的最后一题。四个选项对应材料四个完全不同的知识点，要求选出正确或错误的一项。它不是一道题，而是四道小计算题。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、验证优先级排序（铁律）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "绝不要按 ABCD 的顺序从头推到尾！遵循“避实就虚”原则："}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第一优选（读数题）：找“不涉及计算”的纯常识选项。如“2023年某地市收入不足总体一半”，去材料找个数字比一下即出结果。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第二优选（简单计算）：找“直接相减/直除法”。如“A 比 B 多了约一倍”或“第一季度占比超过了 20%”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第三顺位（定性判定）：找“两期比重/平均数”选项。如“今年比重相比去年上升了”，直接找a和b对比，无硬算。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "最后才碰（硬核计算）：找“基期量计算/增长量极小差距比较/复杂混合增长”。如“2022年 A 比 B 少了多少万吨”。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读四个选项] --> B[在脑子里对它们按计算复杂度排序]\nB --> C[先看最简单、不用列竖式的选项]\nC --> D{它符合题目要求(选对/选错)吗?}\nD -- 符合 --> E[秒选! 剩下三个哪怕不看也不亏!]\nD -- 不符合 --> F[排掉该项, 去看难度第二低的选项]\nF --> G[最后万不得已才去算那个最恶心的选项]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 选出不正确的一项：A. 2022年A省粮食增量比B省多10.5万吨。B. 今年小麦产量不到整体的两成。C. 水稻增速低于玉米增速。D. 今年平均亩产相比去年提升了。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "排序难度：C(直接读数比大小)最简单；D(两期平均判方向，不用硬算)次之；B(现期简单比重验证)第三；A(跨年增长量硬核差值)最恶心。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看 C：回材料找水稻(5%)和玉米(8%)增速，5 < 8，正确。但题目要找“不正确”的，排除 C。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看 D：亩产=产量/面积。产量增10%，面积降2%。a(10%) > b(-2%)，平均数必定上升。选项表述正确，排除 D。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看 B：小麦20吨，整体150吨。两成是 150×20%=30。20 < 30。表述正确，排除 B。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定选项：连 A 都不用看，直接选 A！"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "一根筋算 A 选项：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "A 选项极其繁琐，你花了 3 分钟算出来发现 A 是正确的，于是只好去算 B...这是时间管理上的彻底失败。跳坑是最致命的。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "做最后一道综合题时，拿笔在试卷上给 ABCD 四个选项标上 1,2,3,4 的验证顺序。形成“找软柿子”的强迫症。"}]}]}$$ AS jsonb), NULL, '选项判定的核心考点与实战推导。', category_node.id, CAST('["资料分析", "选项判定"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_option", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
